/**
 * Internacionalização da INTERFACE do portal (as cifras/músicas NÃO são
 * traduzidas — são conteúdo musical e permanecem como estão).
 *
 * Uso:
 *   import { useT } from '../lib/i18n';
 *   const { t, lang, setLang } = useT();
 *   t('header.searchPlaceholder')
 *
 * O idioma é detectado do navegador na primeira visita e pode ser trocado
 * pelo seletor no topo do portal (persistido em localStorage).
 */
