  'trails.t1.title': 'Your First Chord',
  'trails.t1.desc': 'From tuning to your first chord: play 2 complete songs.',
  'trails.t1.s1': 'Tune before you play',
  'trails.t1.s1t': 'Use the app Tuner (G C E A). Tuned strings = great sound and a trained ear.',
  'trails.t1.s2': 'Your first song',
  'trails.t1.s3': 'Change chords in rhythm',
  'trails.t1.s3t': 'Play each chord for 4 beats before switching. Go slow, then speed up gradually.',
