  'trails.t1.s5': 'Use the Simplified version',
  'trails.t1.s5t': 'Simplified chords use basic chords (C, G, Am, F) — perfect for starting.',
  'trails.t2.title': 'Beyond the Basics',
  'trails.t2.desc': 'Barre chords, new rhythms and songs with more chords.',
  'trails.t2.s1': 'Barre chords',
  'trails.t2.s1t': 'Practice F and Bm: the barre needs a straight, firm index finger across all strings.',
  'trails.t2.s2': 'Song with barre chords',
  'trails.t2.s3': 'Different rhythms',
  'trails.t2.s3t': 'Explore the Rhythm Guide in the app: ballad, pop, reggae and xote have different strums.',
  'trails.t2.s4': 'Song for the new rhythm',
  'trails.t2.s5': 'Record yourself playing',
  'trails.t2.s5t': 'Recording and listening back is the fastest way to notice where you get stuck and improve.',
  'trails.t3.title': 'Musical Expression',
  'trails.t3.desc': 'Fingerpicking, inversions and music as conversation.',
  'trails.t3.s1': 'Fingerpicking and arpeggios',
  'trails.t3.s1t': 'Replace strumming with arpeggios: pluck the strings one by one within the chords.',
  'trails.t3.s2': 'Song to fingerpick',
  'trails.t3.s3': 'Inversions and passing chords',
  'trails.t3.s3t': 'Inversions add color to your playing. Try C/G, Am/G and D/F#.',
  'trails.t3.s4': 'Song with inversions',
  'trails.t3.s5': 'Play with others',
  'trails.t3.s5t': 'Join the WhatsApp community and play with other ukulele players — group practice speeds up progress.',
  'trails.t4.title': 'Fundamental Rhythms',
  'trails.t4.desc': 'The strums that hold up any song: down, up and the metronome.',
  'trails.t4.s1': 'Down strum (↓)',
  'trails.t4.s1t': 'Basic strumming: play all strings downward on every beat. Simple and effective.',
  'trails.t4.s2': 'Your first rhythm song',
  'trails.t4.s3': 'Down-up (↓↑)',
  'trails.t4.s3t': 'Alternating down and up adds flow. Count 1-and-2-and-3-and-4-and.',
  'trails.t4.s4': 'Song for the down-up strum',
  'trails.t4.s5': 'Practice with the metronome',
  'trails.t4.s5t': 'Use the app Metronome at 80 BPM and raise it 5 BPM each day.',
  'trails.t5.title': 'Barre Chords in Practice',
  'trails.t5.desc': 'Master F and Bm: the chords that unlock your repertoire.',
  'trails.t5.s1': 'F barre chord',
  'trails.t5.s1t': 'F is your first barre chord: index finger straight on fret 1, ring finger on fret 3.',
  'trails.t5.s2': 'Song with F',
  'trails.t5.s3': 'Bm — barre on fret 2',
  'trails.t5.s3t': 'Bm uses a barre on fret 2. Let your arm weight rest on the index finger.',
  'trails.t5.s4': 'Song with F and Bm',
  'trails.t5.s5': 'Non-stop transitions',
  'trails.t5.s5t': 'Practice the F→Bm→F transition until it flows without looking.',
  'trails.t6.title': 'Rhythms and Grooves',
  'trails.t6.desc': 'Ballad, xote and reggae: bring the groove to your songs.',
  'trails.t6.s1': 'Ballad groove',
  'trails.t6.s1t': 'Ballad: strum the chords on time, gently on the lower strings.',
  'trails.t6.s2': 'Ballad song',
  'trails.t6.s3': 'Xote and baião',
  'trails.t6.s3t': 'Xote: accent beats 2 and 4, with a light hit on the lower strings.',
  'trails.t6.s4': 'Xote song',
  'trails.t6.s5': 'Reggae: the offbeat',
  'trails.t6.s5t': 'In reggae, play on the "and" of each beat (offbeat) to create the swing.',
  'trails.t7.title': 'Advanced Fingerpicking',
  'trails.t7.desc': 'Arpeggios, fingerpicking patterns and dynamics for expressive playing.',
  'trails.t7.s1': 'Arpeggios with the thumb',
  'trails.t7.s1t': 'Use your thumb on the low strings (G, C) and index/middle on the high ones (E, A).',
  'trails.t7.s2': 'Song for arpeggios',
  'trails.t7.s3': 'Fingerpicking pattern',
  'trails.t7.s3t': 'Classic pattern: thumb (G or C), index (E), middle (A), index (E).',
  'trails.t7.s4': 'Song for the pattern',
  'trails.t7.s5': 'Dynamics and expression',
  'trails.t7.s5t': 'Vary the volume: start soft, build up in the chorus and come back down.',
  'trails.t8.title': 'Complete Repertoire',
  'trails.t8.desc': 'Build your setlist, perform and share your music.',
